@Component("room-handler")
@ProcessingGroup("room-processing-group")
public class RoomEventHandler {
	
	// core constructor
	RoomEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRoomEvent
     */
    @EventHandler
    public void handle( CreateRoomEvent event) {
        entityManager.persist(new Room(event.getRoomId(), event.getName(), event.getFloor(), event.getDevices(), event.getGateways()));
    }

    /*
     * @param	event UpdateRoomEvent
     */
    @EventHandler
    public Room handle( UpdateRoomEvent event) {
    	entityManager.merge(new Room(event.getRoomId(), event.getName(), event.getFloor(), event.getDevices(), event.getGateways()));
    }
    
    /*
     * @param	event DeleteRoomEvent
     */
    @EventHandler
    public void on( DeleteRoomEvent event) {
    	Room entity = new Room();
   
    	// ------------------------------------------
    	// apply the RoomId
    	// ------------------------------------------
    	entity.setRoomId( event.getRoomId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RoomRepository roomEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RoomEventHandler.class.getName());

}
